/* Claude.ai Design Kit — Warm Neutral Layout — 84 tokens · 来源:design */
:root{
  --aqua-0: #fff;
  --aqua-10: hsl(150, 50%, 98%);
  --aqua-50: hsl(157, 45%, 92%);
  --aqua-100: hsl(158, 52%, 84%);
  --aqua-200: hsl(157, 54%, 66%);
  --aqua-300: hsl(157, 52%, 49%);
  --aqua-400: hsl(159, 73%, 36%);
  --aqua-500: hsl(162, 79%, 28%);
  --aqua-600: hsl(165, 88%, 20%);
  --aqua-700: hsl(168, 91%, 14%);
  --aqua-800: hsl(169, 90%, 8%);
  --aqua-900: hsl(0, 0%, 4%);
  --blue-0: #fff;
  --blue-10: hsl(216, 100%, 99%);
  --blue-50: hsl(210, 71%, 95%);
  --blue-100: hsl(213, 85%, 89%);
  --blue-200: hsl(213, 80%, 79%);
  --blue-300: hsl(213, 77%, 68%);
  --blue-400: hsl(213, 77%, 56%);
  --blue-500: hsl(213, 68%, 45%);
  --blue-600: hsl(214, 72%, 34%);
  --blue-700: hsl(214, 78%, 24%);
  --blue-800: hsl(212, 91%, 14%);
  --blue-900: hsl(212, 93%, 8%);
  --bg-100: #f8f8f6;
  --bg-200: #efede8;
  --bg-300: #e8e5de;
  --text-100: #121212;
  --text-200: #373734;
  --text-300: #5d5d5a;
  --text-400: #7a7a76;
  --border-100: rgba(11, 11, 11, 0.06);
  --border-200: rgba(11, 11, 11, 0.08);
  --border-300: rgba(11, 11, 11, 0.1);
  --accent-main: hsl(24, 80%, 52%);
  --accent-hover: hsl(24, 80%, 46%);
  --font-sans: 'PingFang SC', 'PingFang TC', -apple-system, BlinkMacSystemFont,
          'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  --font-serif: 'PingFang SC', 'PingFang TC', -apple-system, BlinkMacSystemFont,
          'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
  --font-mono: 'Söhne Mono', 'Fira Code', ui-monospace, monospace;
  --fw-regular: 400;
  --fw-medium: 430;
  --fw-semibold: 560;
  --fw-bold: 700;
  --fs-xs: 11px;
  --fs-sm: 12px;
  --fs-base: 14px;
  --fs-md: 16px;
  --fs-lg: 20px;
  --fs-xl: 24px;
  --fs-2xl: 32px;
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 20px;
  --sp-6: 24px;
  --sp-8: 32px;
  --sp-10: 40px;
  --sp-12: 48px;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 2px 8px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 4px 16px rgba(0, 0, 0, 0.08);
  --motion-hover: 150ms;
  --motion-enter: 280ms;
  --motion-ease: cubic-bezier(0.165, 0.85, 0.45, 1);
  --motion-focus: 0 0 0 3px rgba(11, 11, 11, 0.08);
  --k-bg: var(--bg-100);
  --k-bg-grad: var(--bg-200);
  --k-card: #ffffff;
  --k-card-2: var(--bg-100);
  --k-card-3: var(--bg-200);
  --k-inset: var(--bg-200);
  --k-line: var(--border-100);
  --k-line-2: var(--border-200);
  --k-text: var(--text-100);
  --k-dim: var(--text-300);
  --k-faint: var(--text-400);
  --k-accent: var(--accent-main);
}
